"""Append-only per-placement enemy checks, generated from the supplied gameplay resources.
Alternate age/time headers alias the same physical enemy. Scripted checks use
immutable non-enemy controller identity and a fixed encounter slot. Enemies
created by other enemies (including bosses) never get separate checks.
Retired IDs remain reserved; no death-position or nearest-enemy matching.
"""
from dataclasses import dataclass
from typing import Optional

@dataclass(frozen=True)
class EnemyDropLocationData:
    name: str
    address: int
    scene_id: int
    room: int
    grotto_id: int
    actor_index: int
    actor_id: int
    params: int
    soul_item: Optional[str]
    combat: str
    region_token: str
    spawn_mask: int = 15
    encounter_gate: str = ""

